from taf.fdsw.rc.interfaces.exceptions import OperationFailure
from taf.fdsw.rc.interfaces.FDSW23B.diagnostics import Diagnostics23B
from taf.fdsw.rc.interfaces.FDSW25A.diagnostics.alarm_filter_validators import (
    AlarmFilters,
)
from taf.fdsw.rc.schemas.FDSW25A.diagnostic import Alarms


class Diagnostic25A(Diagnostics23B):

    def get_alarms(self, timeout, limit=None, offset=None, filters=None):
        alarm_filters = AlarmFilters()
        alarm_filters.add_limit(limit)
        alarm_filters.add_offset(offset)
        alarm_filters.add_filters(filters)

        collected_alarms = self._client.send(
            method="diagnostics.alarms.fetch",
            timeout=timeout,
            parameters=alarm_filters.filters,
        )
        if collected_alarms.status is False:
            raise OperationFailure(collected_alarms.error)
        get_alarms = [
            Alarms.from_object_dict(data=alarm) for alarm in collected_alarms.data
        ]
        return [alarm.to_dict() for alarm in get_alarms]

    def count_alarms(self, timeout, filters=None):
        alarm_filters = AlarmFilters()
        alarm_filters.add_filters(filters)

        alarms_count = self._client.send(
            method="diagnostics.alarms.count",
            timeout=timeout,
            parameters=alarm_filters.filters,
        )
        if alarms_count.status is False:
            raise OperationFailure(alarms_count.error)
        return int(alarms_count.data)
